/* 独立低保真原型：所有生成、回填、导出均为本地模拟，无 API。 */
const STORE = 'director-workflow-wireframe-v1';
const stages = [['idea','创意','提供 idea 或导入故事'],['story','故事','比较、选择与编辑'],['script','剧本','修改后再生成分镜'],['shots','分镜','镜头编辑与素材制作'],['export','成品导出','预览、检查与导出']];
const sampleIdea = '一个外卖员在雨夜接到最后一单，却发现收件人是十年前的自己。';
const stories = [
 ['最后一单','温暖 / 自我和解','暴雨里，外卖员林舟接到一份没有电话的订单。收件地址是他十年前住过的老楼。\n\n门开了，少年时代的自己正攥着一封退学申请。林舟认出了桌上的药盒，也想起那一天无人倾听的委屈。他没有透露身份，只陪少年吃完一碗热面。\n\n离开时，他把一张写着“再坚持一天”的纸条压在碗底。回到楼下，手机弹出订单评价：“谢谢你没有放弃我。”林舟望向窗里透出的灯光，重新披上雨衣。'],
 ['迟到的道歉','悬念 / 亲情','林舟在雨夜送达一份十年前的订单。开门的少年竟是过去的自己。\n\n少年正准备离家，桌上有一通未接的父亲来电。林舟知道自己此后再也没有机会接起那个电话。他装作普通外卖员，借充电之名多留片刻，让少年听完父亲的留言。\n\n林舟走出门，手机里出现一段从未有过的合照。他没有改变整个世界，只替自己追回一句迟到的道歉。'],
 ['不签收的未来','反转 / 成长','外卖员林舟送到老楼，订单备注要求他把一张彩票交给少年时代的自己。\n\n那张彩票意味着可以改变未来。但少年不肯签收，他说自己想凭双手把日子过好。林舟终于意识到，自己最怀念的并非轻松生活，而是仍有勇气相信未来的时刻。\n\n他撕掉彩票，将热面留下。雨停时，林舟第一次主动拨通了家里的电话。']
];
const baseScript = '《最后一单》\n\n场一 · 老街 · 夜外\n暴雨。林舟骑车穿过空荡的街道，手机提示最后一单。\n林舟（低声）：送完这一单，就回家。\n\n场二 · 老楼门口 · 夜内\n林舟停在熟悉的门前，敲门。少年抬起头，两人对视。\n少年：你怎么知道我住这里？\n林舟：地址上写着呢。\n\n场三 · 桌边 · 夜内\n少年看着热面，松开手中的退学申请。林舟放下一张纸条。\n林舟：有些路，走慢一点也没关系。\n\n场四 · 楼下 · 夜外\n雨渐停。手机跳出订单评价。林舟回头，看见窗里亮起暖灯。';
function makeShots(){return [
 ['雨夜穿街','老街 · 夜外','林舟骑车穿过空荡街道，雨水在车灯前划出亮线。','送完这一单，就回家。',6],
 ['停在旧门前','老楼门口 · 夜内','林舟抬头看门牌，手停在门铃前。','',5],
 ['门内的少年','旧屋 · 夜内','门缓缓打开，少年与林舟对视。','你怎么知道我住这里？',7],
 ['一碗热面','桌边 · 夜内','热气升起，少年松开攥紧的纸张。','地址上写着呢。',6],
 ['留下纸条','桌边 · 夜内','林舟把纸条压在碗底，手指轻轻停顿。','有些路，走慢一点也没关系。',6],
 ['窗里的灯','老楼外 · 夜外','雨停了，林舟回望亮灯的窗，重新披上雨衣。','',6]
].map((a,i)=>({id:'s'+(i+1),title:a[0],scene:a[1],description:a[2],dialogue:a[3],duration:a[4],video:[0,1,2,5].includes(i)?'sample-video-'+i:'',image:i===4?'sample-image':'',blocking:'',enabled:true,refs:i<3?['a1','a2']:['a1','a3'],review:false}));}
function defaults(empty=false){return {version:1,stage:empty?'idea':'overview',idea:sampleIdea,count:3,ratio:'16:9',style:'写实电影',story:empty?'':stories[0][2],selected:empty?'':'c0',candidates:empty?[]:stories.map((a,i)=>({id:'c'+i,title:a[0],tag:a[1],body:a[2]})),script:empty?'':baseScript,shots:empty?[]:makeShots(),assets:[{id:'a1',kind:'角色',name:'林舟',description:'28岁外卖员，深色雨衣，神情疲惫而温和',image:empty?'':'sample',reference:''},{id:'a2',kind:'场景',name:'老街与旧楼',description:'窄街、老旧住宅、雨夜与窗内暖光',image:'',reference:''},{id:'a3',kind:'道具',name:'外卖保温袋',description:'旧款方形保温袋，有磨损痕迹',image:'',reference:''}],jobs:[],notes:{},annotations:true,tab:'shots',view:'rows',preview:'',expanded:'',checked:[],exportSelected:'s1',subtitle:true,bgm:'无背景音乐',voice:'保留已有配音'};}
let state=defaults();try{const x=JSON.parse(localStorage.getItem(STORE)||'null');if(x?.version===1&&Array.isArray(x.shots))state={...state,...x};}catch{}
const main=document.querySelector('#main'),modal=document.querySelector('#modal'),body=document.querySelector('#modal-body');
let returnFocus=null,modalKind='',pending=null,toastTimer,playing=null;
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,id='',cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" data-id="${E(id)}" ${disabled?'disabled':''}>${label}</button>`;
const badge=(x,outline=false)=>`<span class="badge ${outline?'outline':''}">${x}</span>`;
const annotation=(n,text)=>`<div class="annotation"><b>交互批注 ${n}</b>${text}</div>`;
const frame=(text,ready=false)=>`<div class="frame ${ready?'ready':''}">${E(text)}</div>`;
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));document.querySelector('#save-state').textContent='已保存原型草稿 · 仅本机';}catch{document.querySelector('#save-state').textContent='本机存储不可用 · 本页编辑仍保留';}}
function toast(text){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function dialog(title,content,kind=''){returnFocus=document.activeElement;modalKind=kind;document.querySelector('#modal-title').textContent=title;body.innerHTML=content;if(!modal.open)modal.showModal();}
function close(){modal.close();modalKind='';pending=null;if(returnFocus?.isConnected)returnFocus.focus();}
modal.addEventListener('cancel',()=>{modalKind='';pending=null;});
function go(stage){if(playing){clearInterval(playing);playing=null;}state.stage=stage;render();window.scrollTo({top:0});}
function title(name,desc,actions=''){return `<div class="page-title"><div><h2>${name}</h2><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function editor(field,value,label,readonly=false){return `<label class="field">${label}<textarea class="editor" data-field="${field}" aria-label="${label}" ${readonly?'readonly':''}>${E(value)}</textarea></label>`;}
function render(){document.body.classList.toggle('hide-notes',!state.annotations);document.querySelector('#annotation-toggle').textContent=state.annotations?'隐藏批注':'显示批注';document.querySelector('#annotation-toggle').setAttribute('aria-pressed',String(state.annotations));document.querySelector('#task-count').textContent=state.jobs.length;document.querySelector('#steps').innerHTML=stages.map(([id,name,desc],i)=>`<button class="step ${state.stage===id?'active':''}" data-action="nav" data-id="${id}" ${state.stage===id?'aria-current="step"':''}><span class="step-number">${i+1}</span><span><strong>${name}</strong><small>${desc}</small></span></button>`).join('');main.innerHTML=({overview:overview,idea:idea,story:story,script:script,shots:shotsPage,export:exportPage}[state.stage]||overview)();persist();}
function overview(){return `${title('从一个想法，到一次可控的创作','点击任一阶段查看原型，或沿推荐路径完整走一遍。',badge('低保真 · 交互评审'))}<div class="panel"><span class="caption">WORKFLOW / 人参与每一步</span><div class="flow">${stages.map(([id,name],i)=>`<button class="flow-card" data-action="nav" data-id="${id}"><span class="num">0${i+1}</span><strong>${name}</strong><small>${['输入 idea / 导入故事<br>配置 X 个备选','比较候选 → 采用<br>手工修改后继续','编辑剧情与对白<br>预览分镜生成结果','镜头编辑与排序<br>按需素材 / 直接视频','预览与缺项检查<br>沿用现有导出能力'][i]}</small></button>`).join('')}</div><div class="note"><b>素材是分支，不是强制关卡：</b> 分镜文字 → 直接视频；或角色 / 场景 / 道具 → 按需站位图 → 视频。已有素材可以直接引用。</div>${annotation('01','五阶段导航保持现有创作结构。“成品导出”是原有环节，包含剪映草稿、分镜 / 项目 JSON、SRT 与完整剪辑包。')}</div><div class="journeys" style="margin-top:20px"><article class="journey"><span class="caption">PATH A / 从头创作</span><h3 style="margin-top:12px">从一句 idea 开始</h3><p>生成备选、采用故事、编辑剧本，再进入分镜。</p>${btn('开始这条路径 →','scenario','new','primary')}</article><article class="journey"><span class="caption">PATH B / 已有内容</span><h3 style="margin-top:12px">导入一个成品故事</h3><p>跳过候选生成，直接编辑故事并生成剧本。</p>${btn('体验导入故事 →','import')}</article><article class="journey"><span class="caption">PATH C / 高频工作区</span><h3 style="margin-top:12px">直接检查分镜与导出</h3><p>六个样例镜头，包含视频、静态图和缺失画面。</p>${btn('查看分镜示例 →','scenario','sample')}</article></div><p class="muted" style="font-size:12px;margin:18px 0 0">可编辑内容仅保存在本原型的浏览器草稿。生成使用固定示例；缩略框代表媒体位置，不是真实生成内容。</p>`;}
function idea(){return `${title('01 / 创意','把想拍的内容说清楚，再决定要看几个故事方向。')}<div class="two-col"><section class="panel">${editor('idea',state.idea,'一句话 idea')}<div class="form-row"><label class="field">故事备选数量 X<select data-field="count" aria-label="故事备选数量 X">${[1,2,3,4,5,6].map(n=>`<option ${state.count===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">画幅<select data-field="ratio">${['16:9','9:16','1:1','4:3','3:4','21:9'].map(n=>`<option ${state.ratio===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">风格<select data-field="style">${['写实电影','动画短片','黑白纪实'].map(n=>`<option ${state.style===n?'selected':''}>${n}</option>`).join('')}</select></label></div><details><summary>生成设置 · 文本模型 / 创意 Skill / 篇幅</summary><div class="form-row" style="margin-top:14px"><label class="field">文本模型<select><option>项目默认文本模型（示意）</option></select></label><label class="field">创意 Skill<select><option>剧情短片创意</option><option>无</option></select></label><label class="field">故事篇幅<select><option>500～1000 字</option><option>1000～2000 字</option></select></label></div></details><div class="editor-tools"><span class="muted">本次将生成 <b id="count-copy">${state.count}</b> 个候选，不替换当前故事。</span>${btn('生成 '+state.count+' 个故事方案','generate-stories','','primary')}</div>${annotation('02','只突出当前推进动作；故事数量由用户决定。导入已有故事可以跳过候选生成。')}</section><aside><div class="panel"><h3>已经有故事？</h3><p class="muted">直接粘贴或导入 TXT / MD，进入故事编辑。</p>${btn('导入已有故事','import')}<ul class="rule-list"><li><span>01</span>生成只是提供候选</li><li><span>02</span>选定后仍可人工修改</li><li><span>03</span>不自动进入下一次生成</li></ul></div></aside></div>`;}
function story(){const preview=state.candidates.find(c=>c.id===state.preview);return `${title('02 / 故事','比较故事方向，编辑真正准备拿去生成剧本的正文。',btn('导入故事','import'))}<div class="split-editor"><aside><div class="panel-header"><h3>候选故事 ${state.candidates.length}</h3>${btn('当前稿','current-story','','small')}</div>${state.candidates.map((c,i)=>`<button class="candidate ${state.preview===c.id?'selected':''}" data-action="preview-story" data-id="${c.id}"><small>方案 ${i+1} ${state.selected===c.id?'· 当前采用':''}</small><strong>${E(c.title)}</strong><p>${E(c.tag)}</p><small>点击只预览</small></button>`).join('')||'<div class="note">暂无候选。可从创意生成，也可直接在右侧编写。</div>'}${btn('返回创意，生成候选','nav','idea','small')}</aside><section class="panel"><div class="panel-header"><div><h3>${preview?'预览：'+E(preview.title):'当前故事正文'}</h3><small>${preview?'只读预览 · 当前编辑内容保持不变':'可编辑 · 下次生成使用这份正文'}</small></div>${badge(preview?'预览中':'当前稿',!!preview)}</div>${editor('story',preview?.body??state.story,preview?'候选故事预览':'当前故事正文',!!preview)}${preview?`<div class="editor-tools">${btn('返回当前正文','current-story')}<div class="actions">${btn('采用并编辑','adopt-story',preview.id)}${btn('采用此方案并生成剧本','adopt-script',preview.id,'primary')}</div></div>`:`<div class="editor-tools">${btn('另存为故事方案','save-candidate')}<div class="actions"><span class="muted">剧本 Skill：剧情短片</span>${btn('用当前故事生成剧本','generate-script','','primary',!state.story.trim())}</div></div>`}${annotation('03','预览与采用分离。下一步生成明确使用当前正文；已有剧本会保留到你确认应用新结果。')}</section></div>`;}
function script(){return `${title('03 / 剧本','调整剧情、对白与节奏，再把当前剧本拆成镜头。',btn('返回故事','nav','story'))}<div class="two-col"><section class="panel">${editor('script',state.script,'剧本正文')}<div class="editor-tools">${btn('重新生成剧本','generate-script','','',!state.story.trim())}<div class="actions"><span class="muted">分镜 Skill：电影分镜</span>${btn('用当前剧本生成分镜','generate-shots','','primary',!state.script.trim())}</div></div>${annotation('04','剧本与故事保留独立编辑阶段；生成分镜先预览，再确认应用，避免覆盖已有镜头。')}</section><aside class="panel"><h3>继续前检查</h3><ul class="rule-list"><li>故事与当前剧本是否一致</li><li>对白、动作是否可被拍出来</li><li>节奏和时长是否合适</li></ul><div class="note">原型生成使用固定样例结构，仅演示输入、预览和采用关系。</div></aside></div>`;}
function shotsPage(){if(!state.shots.length)return `${title('04 / 分镜','先生成分镜，或载入样例检查交互。')}<div class="empty"><h3>还没有分镜</h3><p class="muted">可以从当前剧本生成，或查看包含六个镜头的评审样例。</p><div class="actions" style="justify-content:center">${btn('返回剧本','nav','script','primary')}${btn('载入分镜样例','scenario','sample')}</div></div>`;return `${title('04 / 分镜','先看全片，再展开一个镜头。素材可选，支持直接生成视频。',btn('进入成品导出 →','nav','export','primary'))}<div class="tabs">${btn('镜头工作区','tab','shots',state.tab==='shots'?'selected':'')}${btn('项目资产 · '+state.assets.length,'tab','assets',state.tab==='assets'?'selected':'')}</div>${state.tab==='assets'?assetsPage():shotList()}`;}
function shotList(){return `<div class="shot-tools"><div class="actions">${badge(state.shots.length+' 镜头 · '+state.shots.reduce((a,s)=>a+s.duration,0)+' 秒')}${badge(state.shots.filter(s=>s.video).length+' 视频 / '+state.shots.filter(s=>s.image&&!s.video).length+' 静态图')}<small>已选 ${state.checked.length} 项</small></div><div class="actions">${btn(state.view==='rows'?'表格编辑':'紧凑总览','view')}${btn('生成所选视频','batch','','',!state.checked.length)}${btn('查看任务','tasks')}</div></div>${state.view==='table'?table():`<div class="shot-list"><div class="shot-head"><input type="checkbox" aria-label="选择全部镜头" data-action="check-all" ${state.checked.length===state.shots.length?'checked':''}><span>镜头</span><span>画面</span><span>内容摘要 / 引用</span><span>时长</span><span>素材状态</span><span>操作</span></div>${state.shots.map((s,i)=>`<article class="shot-card" id="shot-${s.id}"><div class="shot-row"><input type="checkbox" aria-label="选择镜头 ${i+1}" data-action="check-shot" data-id="${s.id}" ${state.checked.includes(s.id)?'checked':''}><span class="num">${String(i+1).padStart(2,'0')}</span><button class="frame ${s.video||s.image?'ready':''}" data-action="preview-shot" data-id="${s.id}" aria-label="预览镜头 ${i+1}">${s.video?'▷ 视频示意':s.image?'静态图示意':'暂无画面'}</button><div class="row-title"><strong>${E(s.title)}</strong><p>${E(s.description)}</p><small>${E(s.scene)} · ${s.refs.length} 项引用 ${s.blocking?'· 有站位图':''}</small></div><span>${s.duration}s</span><div>${badge(s.review?'待复核':s.video?'已有视频':s.image?'已有图片':'待制作',!s.video)}<small style="display:block;margin-top:4px">${s.dialogue?'有台词':'无台词'}</small></div><div class="actions">${btn(state.expanded===s.id?'收起':'编辑','expand',s.id,'small')}${btn('生成视频','generate-video',s.id,'small')}</div></div>${state.expanded===s.id?shotDetail(s,i):''}</article>`).join('')}</div>`}${annotation('05','图片只预览，复选框只选择，“编辑”展开详情。空字段不撑高摘要；模型、提示词和资产操作放在镜头详情。')}`;}
function shotDetail(s,i){return `<div class="shot-detail"><div><div class="panel-header"><h3>镜头 ${i+1} · 内容与声音</h3><div class="actions">${btn('上移','move-up',s.id,'small',i===0)}${btn('下移','move-down',s.id,'small',i===state.shots.length-1)}</div></div><label class="field">画面描述<textarea data-shot="${s.id}" data-prop="description">${E(s.description)}</textarea></label><div class="form-row"><label class="field">镜头名称<input type="text" data-shot="${s.id}" data-prop="title" value="${E(s.title)}"></label><label class="field">时长（秒）<input type="number" min="1" max="120" data-shot="${s.id}" data-prop="duration" value="${s.duration}"></label><label class="field">声音路线<select data-shot="${s.id}" data-prop="sound"><option>模型原声</option><option ${s.sound==='独立配音'?'selected':''}>独立配音</option><option ${s.sound==='无声'?'selected':''}>无声</option></select></label></div><label class="field">台词（可留空）<textarea data-shot="${s.id}" data-prop="dialogue">${E(s.dialogue)}</textarea></label></div><div><h3>画面参考 <small>按需准备</small></h3><div class="references">${state.assets.map(a=>`<label class="check-label"><input type="checkbox" data-ref="${s.id}" value="${a.id}" ${s.refs.includes(a.id)?'checked':''}>${E(a.name)} ${a.image?'· 有图':''}</label>`).join('')}</div><div class="actions">${btn('管理角色 / 场景 / 道具','tab','assets','small')}${btn(s.blocking?'重做站位图':'生成站位图','generate-blocking',s.id,'small')}${btn('上传已有画面','upload-shot',s.id,'small')}</div><div class="note">没有图片也可用支持文生视频的模型直接生成。站位图用于说明人物位置、朝向和机位，不是必填项。</div><details style="margin-top:18px"><summary>提示词与高级参数</summary><label class="field" style="margin-top:10px">视频提示词<textarea data-shot="${s.id}" data-prop="prompt">${E(s.prompt||s.description)}</textarea></label></details><div class="editor-tools">${btn('更多操作','shot-more',s.id,'small')}${btn('生成视频','generate-video',s.id,'primary')}</div></div></div>`;}
function table(){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>镜头</th><th>画面描述</th><th>台词</th><th>秒</th><th>操作</th></tr></thead><tbody>${state.shots.map((s,i)=>`<tr><td>${i+1} · ${E(s.title)}</td><td><textarea data-shot="${s.id}" data-prop="description" aria-label="镜头${i+1}画面描述">${E(s.description)}</textarea></td><td><textarea data-shot="${s.id}" data-prop="dialogue" aria-label="镜头${i+1}台词">${E(s.dialogue)}</textarea></td><td><input type="number" min="1" max="120" value="${s.duration}" data-shot="${s.id}" data-prop="duration" aria-label="镜头${i+1}秒数"></td><td>${btn('生成视频','generate-video',s.id,'small')}</td></tr>`).join('')}</tbody></table></div>`;}
function assetsPage(){return `<div class="panel-header"><span class="muted">同一角色 / 场景可被多个镜头引用；资产图片按需生成。</span>${btn('返回镜头工作区','tab','shots')}</div><div class="asset-grid">${state.assets.map(a=>`<article class="panel asset-card">${frame(a.image?'当前图片 · 示意':'尚无当前图片',!!a.image)}<h3>${E(a.name)} ${badge(a.kind)}</h3><p>${E(a.description)}</p><small>生成参考图：${a.reference?'已选择':'未选择'} · 当前使用图片：${a.image?'已有':'无'}</small><div class="actions">${btn('编辑与参考图','edit-asset',a.id,'small')}${btn(a.image?'重新生成图片':'生成图片','generate-asset',a.id,'small')}</div></article>`).join('')}</div>${annotation('06','参考图和当前使用图片分别命名。图像不是视频生成的统一前置条件；已有素材和文生视频都保留。')}`;}
function exportPage(){const enabled=state.shots.filter(s=>s.enabled),missing=enabled.filter(s=>!s.video&&!s.image),selected=enabled.find(s=>s.id===state.exportSelected)||enabled[0];return `${title('05 / 成品导出','沿用现有环节：检查画面、配音与字幕，再选择交付方式。',btn('导出选项','export-dialog','','primary',!enabled.length))}${!enabled.length?`<div class="empty"><h3>还没有可预览的镜头</h3>${btn('返回分镜','nav','shots')}</div>`:`<div class="preview-grid"><section class="panel"><div class="player"><span class="label">镜头顺序预览 · 非渲染成片</span><span class="play-mark">▷</span><strong id="player-title">${E(selected.title)}</strong><small id="player-desc">${E(selected.description)}</small><small>低保真占位画面，不含真实视频</small></div><div class="timeline">${enabled.map((s,i)=>`<button class="${s.id===selected.id?'selected':''}" data-action="timeline" data-id="${s.id}">${String(i+1).padStart(2,'0')} ${s.duration}s<small>${s.video?'视频':s.image?'图片':'缺画面'}</small></button>`).join('')}</div><div class="actions">${btn(playing?'停止演示播放':'演示顺序播放','play')}${btn('编辑当前镜头','locate-shot',selected.id)}<span class="muted">共 ${enabled.reduce((n,s)=>n+s.duration,0)} 秒 · ${state.ratio}</span></div><div class="form-row" style="margin-top:18px"><label class="field">配音<select data-field="voice"><option ${state.voice==='保留已有配音'?'selected':''}>保留已有配音</option><option ${state.voice==='仅模型原声'?'selected':''}>仅模型原声</option></select></label><label class="field">BGM<select data-field="bgm"><option ${state.bgm==='无背景音乐'?'selected':''}>无背景音乐</option><option ${state.bgm==='示例背景音乐'?'selected':''}>示例背景音乐</option></select></label><label class="check-label"><input type="checkbox" data-field="subtitle" ${state.subtitle?'checked':''}>包含字幕</label></div></section><aside class="panel"><h3>导出前检查</h3><div class="issue"><span>画面已准备</span><b>${enabled.length-missing.length} / ${enabled.length}</b></div><div class="issue"><span>视频 / 静态图</span><b>${enabled.filter(s=>s.video).length} / ${enabled.filter(s=>!s.video&&s.image).length}</b></div><div class="issue"><span>待复核镜头</span><b>${enabled.filter(s=>s.review).length}</b></div>${missing.length?missing.map(s=>`<div class="issue"><span>镜头 ${state.shots.indexOf(s)+1} 缺少画面</span>${btn('去补齐','locate-shot',s.id,'small')}</div>`).join(''):'<p style="margin-top:14px">所有启用镜头均有画面。</p>'}<div class="note">无 BGM、无对白不是错误。静态图片可继续使用；缺少画面的镜头会在导出时再次提示。</div></aside></div><div class="export-options"><article class="panel"><h3>去剪映继续剪辑</h3><p>剪映草稿保留画面、配音、字幕与背景音乐轨道。</p>${btn('导出剪映草稿','export-type','jianying','primary')}</article><article class="panel"><h3>素材与字幕</h3><p>完整剪辑包包含素材和渲染工具；字幕也可单独下载。</p><div class="actions">${btn('完整剪辑包','export-type','kit')}${btn('字幕 SRT','export-type','srt','small')}</div></article><article class="panel"><h3>项目与分镜备份</h3><p>JSON 记录结构化内容，不等于包含全部媒体的成片文件。</p><div class="actions">${btn('项目 JSON','export-type','project')}${btn('分镜 JSON','export-type','shots','small')}</div></article></div>${annotation('07','“成品导出”保持为最后阶段，能力与现有系统一致。最终 MP4 在剪映或剪辑包附带的外部渲染工具中完成，不新增一键 MP4。')}`}`;}
function tasks(){dialog('生成任务 · 雨夜的最后一单',`<p class="muted">结果先展示对象与画面，模型和提示词收在详情中。全部为模拟任务。</p>${state.jobs.length?state.jobs.slice().reverse().map(j=>{const target=j.type==='asset'?state.assets.find(a=>a.id===j.target):state.shots.find(s=>s.id===j.target);const current=target?.[j.type==='asset'?'image':j.type==='blocking'?'blocking':'video']===j.id;return `<article class="task-card"><div>${frame(j.status==='ready'?'生成结果 · 示意':j.status==='failed'?'生成失败':'处理中',j.status==='ready')}<div><h3>${E(j.name)}</h3>${badge(j.status==='ready'?'结果就绪':j.status==='failed'?'失败':'生成中')} ${current?badge('当前使用'):j.status==='ready'?badge('可预览 / 采用',true):''}</div></div><div class="actions">${btn('预览并采用','result',j.id,'small',j.status!=='ready')}${btn('返回对象','locate-job',j.id,'small',!target)}${j.status==='failed'?btn('查看原因','job-error',j.id,'small'):''}</div><details><summary>模型、提示词与记录</summary><p>模型：${E(j.model)}<br>提示词：${E(j.prompt)}<br>记录：${j.id}</p></details></article>`;}).join(''):'<div class="empty">暂无任务。可在镜头中生成视频，或在项目资产中生成图片。</div>'}`,'tasks');}
function openGeneration(ids,type='video'){const objs=ids.map(id=>type==='asset'?state.assets.find(a=>a.id===id):state.shots.find(s=>s.id===id)).filter(Boolean);if(!objs.length)return;pending={ids,type};dialog(type==='asset'?'生成资产图片':type==='blocking'?'生成站位图':objs.length>1?'生成所选镜头视频':'生成视频',`<p>本次对象：<b>${objs.map(o=>E(o.title||o.name)).join('、')}</b></p><label class="field">生成模型<select id="gen-model"><option value="text">${type==='video'?'文生视频 · 支持无参考图':'项目默认图片模型'}（示意）</option>${type==='video'?'<option value="image">图生视频 · 必须有参考图（示意）</option>':''}</select></label>${type==='video'?'<label class="check-label"><input type="checkbox" id="gen-use-refs" checked>使用这些镜头已具备的参考图片</label>':''}${type==='asset'&&objs[0].kind==='角色'?'<label class="check-label"><input type="checkbox" checked>生成角色三视图</label>':''}<label class="field">本次提示词<textarea id="gen-prompt">${E(objs[0].prompt||objs[0].description)}</textarea></label><div id="gen-error" role="alert"></div><details><summary>评审工具：模拟失败状态</summary><label class="check-label"><input type="checkbox" id="gen-fail">本次返回失败，检查错误恢复入口</label></details><div class="note">模拟提交 ${objs.length} 项，不调用模型、不消耗额度。已有素材保留，待你采用新结果。</div><div class="actions">${btn('取消','close')}${btn('确认生成（模拟）','submit-generation','','primary')}</div>`,'generation');pending={ids,type};}
function submitGeneration(){if(!pending)return;const {ids,type}=pending;const model=document.querySelector('#gen-model').value,useRefs=document.querySelector('#gen-use-refs')?.checked;const prompt=document.querySelector('#gen-prompt').value,fail=document.querySelector('#gen-fail')?.checked;if(type==='video'&&model==='image'){const invalid=ids.some(id=>{const s=state.shots.find(x=>x.id===id);return !s||!useRefs||!(s.image||s.blocking||s.refs.some(r=>state.assets.find(a=>a.id===r)?.image));});if(invalid){document.querySelector('#gen-error').innerHTML='<div class="inline-warning">当前模型要求参考图。请选用已有图片，或切换支持无图的文生视频模型。</div>';return;}}
 const jobs=ids.map(id=>{const o=type==='asset'?state.assets.find(a=>a.id===id):state.shots.find(s=>s.id===id);return {id:'demo-'+Date.now()+'-'+id,target:id,type,status:'running',name:type==='asset'?o.name+' · 图片':o.title+' · '+(type==='blocking'?'站位图':'视频'),model:model==='image'?'图生视频模型（示意）':'项目默认模型（示意）',prompt};});state.jobs.push(...jobs);close();render();toast('已模拟提交，可继续编辑或打开生成任务。');setTimeout(()=>{jobs.forEach(j=>{const job=state.jobs.find(x=>x.id===j.id);if(job)job.status=fail?'failed':'ready';});persist();if(modalKind==='tasks')tasks();else if(state.jobs.some(x=>jobs.some(j=>j.id===x.id)))toast(fail?'模拟任务失败；到任务列表查看原因。':'模拟结果已就绪，打开生成任务预览并采用。');},850);}
function result(id){const j=state.jobs.find(x=>x.id===id);if(!j)return;dialog(j.name,`${frame('结果占位 · '+j.name,true)}<p style="margin-top:18px">${j.type==='asset'?'采用后设为该资产的当前使用图片。':'采用后替换原对象的当前素材；其他镜头不变。'}</p><div class="note">原型展示位置与采用关系，不包含真实模型生成的媒体。</div><div class="actions">${btn('返回任务','tasks')}${btn('采用到原对象','apply-result',j.id,'primary')}</div>`,'result');}
const exportNames={jianying:'剪映草稿',kit:'完整剪辑包',srt:'字幕 SRT',project:'项目 JSON',shots:'分镜 JSON'};
function exportDialog(type){if(!type){dialog('成品导出 · 选择交付方式',`<p>沿用现有系统的五类导出。最终 MP4 由剪映或剪辑包中的外部工具生成。</p>${Object.entries(exportNames).map(([id,name])=>`<div class="issue"><span>${name}</span>${btn('选择','export-type',id)}</div>`).join('')}<div class="note">剪辑包包含素材、项目、字幕和本机渲染工具，需要 Python + FFmpeg。JSON 不包含全部媒体文件。</div>`,'export-options');return;}
 const missing=state.shots.filter(s=>s.enabled&&!s.video&&!s.image),needsMedia=['jianying','kit'].includes(type);dialog('导出'+exportNames[type],`<p>项目：雨夜的最后一单 · ${state.ratio} · ${state.shots.filter(s=>s.enabled).length} 个启用镜头</p>${needsMedia?'<label class="field">保存位置（示意）<input readonly value="系统原生目录选择窗口确定的位置"></label><small>正式版沿用系统原生目录选择；此原型不会访问或写入实际目录。</small>':''}${needsMedia&&missing.length?`<div class="inline-warning">镜头 ${missing.map(s=>state.shots.indexOf(s)+1).join('、')} 缺少画面。可返回补齐，也可继续导出已有内容；这不代表完整成片。</div>`:''}<div class="note">${type==='jianying'?'导出后在剪映中打开草稿继续剪辑。':type==='kit'?'包含素材、项目、字幕和渲染工具，最终 MP4 需外部渲染。':type==='srt'?'导出当前镜头台词对应的字幕。':'导出结构化记录，媒体文件不会全部嵌入 JSON。'}</div><div class="actions">${needsMedia&&missing.length?btn('返回缺失镜头','locate-shot',missing[0].id):btn('取消','close')}${btn('确认导出（模拟）','confirm-export',type,'primary')}</div>`,'export-confirm');}
function importStory(){dialog('导入成品故事',`<p class="muted">导入后直接进入故事编辑，跳过生成备选；现有下游内容不会被自动删除。</p><label class="field">故事正文<textarea id="import-text" class="editor" placeholder="粘贴故事，或选择 TXT / MD 文件"></textarea></label><div class="actions" style="justify-content:space-between">${btn('选择 TXT / MD 文件','import-file')}${btn('填入示例故事','import-example')}</div><div id="import-error" role="alert"></div><div class="actions">${btn('取消','close')}${btn('导入并编辑故事','apply-import','','primary')}</div>`,'import');}
function chooseFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.addEventListener('change',async()=>{const file=input.files?.[0];if(file)await callback(file);});input.click();}
function review(){const label=stages.find(x=>x[0]===state.stage)?.[1]||'流程总览';dialog('记录审核意见',`<div class="review-status">当前页面：<b>${label}</b> · 意见仅保存在本机</div><label class="field">你的意见<textarea data-note="${state.stage}" aria-label="你的意见" placeholder="例如：镜头摘要再加一项信息；主动作换个位置……">${E(state.notes[state.stage]||'')}</textarea></label><p class="muted">可切换页面分别记录；导出文本后发给我即可继续修订。</p><div class="actions">${btn('导出全部审核意见','download-notes')}${btn('保存意见','save-notes','','primary')}</div>`,'review');}
function syncAssetModal(id){if(modalKind!=='asset'||body.dataset.asset!==id)return;const asset=state.assets.find(x=>x.id===id),frames=body.querySelectorAll('.frame');frames[0].textContent=asset.reference?'已选参考图：'+asset.reference:'未选择';frames[1].textContent=asset.image?'已有图片':'尚无图片';frames[1].classList.toggle('ready',!!asset.image);body.querySelector('[data-action="clear-asset"]').disabled=!asset.image;}
function downloadNotes(){const contents=['AI 短片工作台 · 低保真原型 V0.1 审核意见',...Object.entries(state.notes).filter(([,v])=>v.trim()).map(([k,v])=>'\n【'+(stages.find(x=>x[0]===k)?.[1]||'流程总览')+'】\n'+v)].join('\n');const url=URL.createObjectURL(new Blob([contents],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='交互原型审核意见.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出审核意见文本。');}
function createCandidates(){if(!state.idea.trim())return toast('请先填写一句话 idea。');if(state.candidates.length+state.count>12)return toast('最多保留12个候选；请先删除不再需要的候选或减少数量。');const candidates=Array.from({length:state.count},(_,i)=>{const base=stories[i%stories.length];return {id:'c'+Date.now()+'-'+i,title:base[0]+(i>=3?' · 变体'+(i+1):''),tag:base[1],body:'创作输入：'+state.idea+'\n\n'+base[2]};});state.candidates.push(...candidates);state.preview=candidates[0].id;go('story');toast('已模拟生成 '+state.count+' 个候选；点击“采用并编辑”选用。');}
function scriptCandidate(candidateId){const c=state.candidates.find(x=>x.id===candidateId);const source=c?.body||state.story;if(!source.trim())return toast('请先填写或采用故事。');pending={source,candidateId};dialog('预览生成的剧本',`<p class="muted">输入来源：${c?'候选故事「'+E(c.title)+'」':'当前编辑的故事正文'}。采用结果前保留原剧本。</p><details><summary>查看本次使用的故事</summary><p style="white-space:pre-wrap">${E(source)}</p></details><label class="field" style="margin-top:15px">剧本生成结果（固定样例，可编辑）<textarea id="generated-script" class="editor">${E(baseScript)}</textarea></label><div class="actions">${btn('取消，保留原稿','close')}${btn('采用剧本并继续编辑','apply-script','','primary')}</div>`,'script-candidate');pending={source,candidateId};}
function shotCandidate(){if(!state.script.trim())return toast('请先填写剧本。');dialog('预览分镜生成结果',`<p>基于当前剧本提交。以下为原型固定样例，可在采用后逐镜头编辑。</p><p class="muted">${state.shots.length?'应用将替换当前分镜列表；原型仅用于演示，正式版须保留撤销/原稿。':'应用后进入分镜工作区。'}</p>${makeShots().map((s,i)=>`<div class="issue"><span>${i+1} · ${E(s.title)}</span><span>${s.duration}s</span></div>`).join('')}<div class="actions">${btn('取消，保留当前分镜','close')}${btn('确认应用分镜','apply-shots','','primary')}</div>`,'shot-candidate');}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.note){state.notes[t.dataset.note]=t.value;persist();return;}if(t.dataset.field){const key=t.dataset.field;state[key]=key==='count'?Number(t.value):t.type==='checkbox'?t.checked:t.value;persist();if(key==='count'){document.querySelector('#count-copy').textContent=state.count;document.querySelector('[data-action="generate-stories"]').textContent='生成 '+state.count+' 个故事方案';}return;}if(t.dataset.shot){const s=state.shots.find(x=>x.id===t.dataset.shot);if(!s)return;const key=t.dataset.prop;if(key==='duration'){const n=Number(t.value);if(!Number.isFinite(n)||n<1||n>120){t.setCustomValidity('时长应为1～120秒');return;}t.setCustomValidity('');s.duration=n;}else s[key]=t.value;if(s.video)s.review=true;persist();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.ref){const s=state.shots.find(x=>x.id===t.dataset.ref);if(t.checked)s.refs=[...new Set([...s.refs,t.value])];else s.refs=s.refs.filter(r=>r!==t.value);persist();}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t||t.disabled)return;const a=t.dataset.action,id=t.dataset.id;const s=state.shots.find(x=>x.id===id);
 switch(a){
 case 'nav':go(id);break;case 'overview':go('overview');break;case 'asset-nav':state.tab='assets';go('shots');break;
 case 'annotations':state.annotations=!state.annotations;render();break;case 'review':review();break;case 'save':persist();toast('原型草稿已保存在本机浏览器。');break;
 case 'reset':case 'scenario':pending={scenario:a==='reset'?'new':id};dialog('切换演示场景',`<p>将${a==='reset'||id==='new'?'从 idea 开始':'载入分镜与导出样例'}，替换本原型中的演示编辑。已记录的审核意见保留，不影响正式项目。</p><div class="actions">${btn('取消','close')}${btn('确认切换','confirm-scenario','','primary')}</div>`,'scenario');pending={scenario:a==='reset'?'new':id};break;
 case 'confirm-scenario':{const which=pending.scenario,notes=state.notes,ann=state.annotations;close();state=defaults(which==='new');state.notes=notes;state.annotations=ann;go(which==='new'?'idea':'shots');break;}
 case 'close':close();break;case 'save-notes':persist();close();toast('审核意见已保存。');break;case 'download-notes':downloadNotes();break;
 case 'generate-stories':createCandidates();break;case 'preview-story':state.preview=id;render();break;case 'current-story':state.preview='';render();break;
 case 'adopt-story':{const c=state.candidates.find(x=>x.id===id);state.story=c.body;state.selected=c.id;state.preview='';state.shots.forEach(s=>{if(s.video)s.review=true;});render();toast('已采用该故事，可继续手工编辑。');break;}
 case 'save-candidate':if(!state.story.trim())return toast('当前故事为空。');if(state.candidates.length>=12)return toast('已达到12个候选。');state.candidates.push({id:'manual-'+Date.now(),title:'人工编辑稿 '+(state.candidates.length+1),tag:'手动保存',body:state.story});render();toast('已另存，当前正文保持不变。');break;
 case 'generate-script':scriptCandidate();break;case 'adopt-script':scriptCandidate(id);break;
 case 'apply-script':{const text=document.querySelector('#generated-script').value;if(!text.trim())return toast('剧本内容不能为空。');if(pending.candidateId){state.story=pending.source;state.selected=pending.candidateId;state.preview='';}state.script=text;state.shots.forEach(s=>s.review=true);close();go('script');break;}
 case 'generate-shots':shotCandidate();break;case 'apply-shots':state.shots=makeShots().map(s=>({...s,video:'',image:'',blocking:''}));state.checked=[];state.expanded='';close();go('shots');break;
 case 'import':importStory();break;case 'import-example':document.querySelector('#import-text').value=stories[1][2];break;case 'import-file':chooseFile('.txt,.md',async file=>{if(file.size>400000)return toast('原型接受400KB以内的文本文件。');document.querySelector('#import-text').value=await file.text();});break;
 case 'apply-import':{const val=document.querySelector('#import-text').value;if(!val.trim()){document.querySelector('#import-error').innerHTML='<div class="inline-warning">请粘贴故事或选择文件。</div>';return;}state.story=val;state.selected='';state.preview='';state.shots.forEach(s=>s.review=true);close();go('story');toast('已导入故事，可编辑后生成剧本。');break;}
 case 'tab':state.tab=id;render();break;case 'view':state.view=state.view==='rows'?'table':'rows';render();break;
 case 'expand':state.expanded=state.expanded===id?'':id;render();break;
 case 'check-shot':state.checked=t.checked?[...new Set([...state.checked,id])]:state.checked.filter(x=>x!==id);render();break;case 'check-all':state.checked=t.checked?state.shots.map(x=>x.id):[];render();break;
 case 'move-up':case 'move-down':{const i=state.shots.indexOf(s),j=i+(a==='move-up'?-1:1);if(j>=0&&j<state.shots.length)[state.shots[i],state.shots[j]]=[state.shots[j],state.shots[i]];render();break;}
 case 'shot-more':dialog('镜头操作 · '+s.title,`<p>删除只影响当前镜头；生成任务保留历史记录。</p><div class="actions">${btn(s.enabled?'停用此镜头':'启用此镜头','toggle-shot',id)}${btn('删除此镜头','delete-shot',id,'danger')}</div>`);break;
 case 'toggle-shot':s.enabled=!s.enabled;close();render();break;case 'delete-shot':dialog('确认删除此镜头？',`<p>${E(s.title)} 将从原型中移除，其他镜头保留。</p><div class="actions">${btn('取消','close')}${btn('确认删除','confirm-delete',id,'primary')}</div>`);break;
 case 'confirm-delete':state.shots=state.shots.filter(x=>x.id!==id);state.checked=state.checked.filter(x=>x!==id);close();render();break;
 case 'generate-video':openGeneration([id]);break;case 'batch':openGeneration(state.checked);break;case 'generate-blocking':openGeneration([id],'blocking');break;case 'generate-asset':openGeneration([id],'asset');break;case 'submit-generation':submitGeneration();break;
 case 'tasks':tasks();break;case 'result':result(id);break;case 'job-error':dialog('模拟失败原因',`<p>供应商返回超时，当前素材保持不变。正式系统需先核对原任务，再决定是否重试。</p><div class="actions">${btn('返回任务列表','tasks','','primary')}</div>`);break;
 case 'apply-result':{const j=state.jobs.find(x=>x.id===id),target=j.type==='asset'?state.assets.find(x=>x.id===j.target):state.shots.find(x=>x.id===j.target);if(!target)return toast('原对象已删除，不能应用到其他镜头。');target[j.type==='asset'?'image':j.type==='blocking'?'blocking':'video']=j.id;target.review=false;persist();tasks();render();toast('已采用到原对象，其他镜头不变。');break;}
 case 'locate-job':{const j=state.jobs.find(x=>x.id===id);close();state.tab=j.type==='asset'?'assets':'shots';state.expanded=j.target;go('shots');break;}
 case 'locate-shot':if(modal.open)close();state.tab='shots';state.expanded=id;go('shots');document.querySelector('#shot-'+id)?.scrollIntoView({block:'center'});break;
 case 'preview-shot':dialog('镜头预览 · '+s.title,`${frame(s.video?'当前视频占位':s.image?'当前图片占位':'尚无画面',!!(s.video||s.image))}<p style="margin-top:18px">${E(s.description)}</p><div class="note">用于评审预览位置与返回流程；不播放真实素材。</div><div class="actions">${btn('关闭预览','close')}${btn('编辑此镜头','locate-shot',id)}</div>`);break;
 case 'edit-asset':{const o=state.assets.find(x=>x.id===id);dialog('编辑资产 · '+o.name,`<label class="field">名称<input id="asset-name" value="${E(o.name)}"></label><label class="field">描述<textarea id="asset-description">${E(o.description)}</textarea></label><div class="form-row"><div><h3>生成参考图</h3>${frame(o.reference?'已选参考图':'未选择')}<div class="actions">${btn('选择参考图','upload-reference',id,'small')}${btn('清除参考','clear-reference',id,'small')}</div></div><div><h3>当前使用图片</h3>${frame(o.image?'已有图片':'尚无图片',!!o.image)}${btn('清除当前图','clear-asset',id,'small',!o.image)}</div></div><div class="note">选择图片调用浏览器原生文件窗口。正式桌面版继续保留现有原生目录及图片选择。</div><div class="actions">${btn('取消','close')}${btn('保存资产','save-asset',id,'primary')}</div>`,'asset');body.dataset.asset=id;break;}
 case 'save-asset':{const o=state.assets.find(x=>x.id===id);o.name=document.querySelector('#asset-name').value.trim()||o.name;o.description=document.querySelector('#asset-description').value;close();render();break;}
 case 'upload-reference':chooseFile('image/*',async file=>{state.assets.find(x=>x.id===id).reference=file.name;persist();syncAssetModal(id);toast('已选择参考：'+file.name+'（只记录名称）');});break;
 case 'clear-reference':state.assets.find(x=>x.id===id).reference='';persist();syncAssetModal(id);toast('已清除参考图。');break;case 'clear-asset':state.assets.find(x=>x.id===id).image='';persist();syncAssetModal(id);toast('已清除当前图，不从历史自动回显。');break;
 case 'upload-shot':chooseFile('image/*,video/*',async file=>{s[file.type.startsWith('video/')?'video':'image']='local-demo-'+file.name;s.review=false;render();toast('已引用文件名：'+file.name+'；原型不上传文件。');});break;
 case 'timeline':state.exportSelected=id;render();break;
 case 'play':if(playing){clearInterval(playing);playing=null;render();}else{playing=setInterval(()=>{const list=state.shots.filter(x=>x.enabled);const i=list.findIndex(x=>x.id===state.exportSelected);state.exportSelected=list[(i+1)%list.length].id;render();},1500);render();}break;
 case 'export-dialog':exportDialog();break;case 'export-type':exportDialog(id);break;
 case 'confirm-export':dialog('正在模拟导出',`<p>${exportNames[id]} · 不创建真实文件</p><div class="progress"></div>`,'exporting');setTimeout(()=>{if(modalKind!=='exporting')return;dialog('导出流程演示完成',`<h3>${exportNames[id]} · 模拟成功</h3><p>${id==='jianying'?'正式版在剪映中打开草稿，继续剪辑并导出最终视频。':id==='kit'?'正式版下载剪辑包后，可使用随包工具和 Python + FFmpeg 渲染。':'正式版将下载对应结构化文件或字幕。'}</p><div class="note">本原型没有生成、下载或写入真实项目文件。</div><div class="actions">${btn('返回成品导出','close','','primary')}</div>`,'export-done');},650);break;
 }
});
render();
